#include <iostream>
using namespace std;

void convert_u16_to_string(const unsigned short *value,const unsigned short length) {
    for (int i = 0; i < length;i++){
    unsigned char msB = value[i] >> 8;
    unsigned char lsB = value[i] & 255;

    unsigned char HEX_0 = msB >> 4;
    unsigned char HEX_1 = msB & 15;

    unsigned char HEX_2 = lsB >> 4;
    unsigned char HEX_3 = lsB & 15;

    unsigned char char_array[] = "0000";

    // cout << ("MSB: ");
    // cout << ((int)msB);
    // cout << (" LSB: ");
    // cout << ((int)lsB) << endl;

    // cout << ((int)HEX_0);
    // cout << (" ");
    // cout << ((int)HEX_1);
    // cout << (" ");
    // cout << ((int)HEX_2);
    // cout << (" ");
    // cout << ((int)HEX_3) << endl;
    // cout << endl;

    // cout << ((int)HEX_0 + 'A');
    // cout << (" ");
    // cout << ((int)HEX_1 + 'A');
    // cout << (" ");
    // cout << ((int)HEX_2 + 'A');
    // cout << (" ");
    // cout << ((int)HEX_3 + 'A') << endl;
    // cout << endl;

    char_array[0] = (HEX_0 + 'A');
    char_array[1] = (HEX_1 + 'A');
    char_array[2] = (HEX_2 + 'A');
    char_array[3] = (HEX_3 + 'A');

    cout << char_array;
    }
    cout << endl << endl;
}

